#define MAX_N 300
#define INF 1000000000

typedef long long ll;

int n, m, l;
ll dist[MAX_N][MAX_N];
int fuel[MAX_N][MAX_N];

int main() {
    scanf("%d %d %d", &n, &m, &l);

    // Initialize distances
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < n; j++) {
            if (i == j) dist[i][j] = 0;
            else dist[i][j] = INF;
        }
    }

    // Read roads
    for (int i = 0; i < m; i++) {
        int a, b;
        ll c;
        scanf("%d %d %lld", &a, &b, &c);
        a--; b--;
        if (c <= l) {
            dist[a][b] = c;
            dist[b][a] = c;
        }
    }

    // Floyd-Warshall for shortest paths
    for (int k = 0; k < n; k++) {
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (dist[i][k] + dist[k][j] < dist[i][j]) {
                    dist[i][j] = dist[i][k] + dist[k][j];
                }
            }
        }
    }

    // Build fuel consumption graph
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < n; j++) {
            if (i == j) fuel[i][j] = 0;
            else if (dist[i][j] <= l) fuel[i][j] = 1;
            else fuel[i][j] = INF;
        }
    }

    // Floyd-Warshall for minimum refuels
    for (int k = 0; k < n; k++) {
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
