int main(void) {
    int N, M;
    long long L;
    if (scanf("%d %d %lld", &N, &M, &L) != 3) return 0;

    long long *dist = (long long *)malloc((size_t)N * N * sizeof(long long));
    long long *fuel = (long long *)malloc((size_t)N * N * sizeof(long long));
    if (!dist || !fuel) return 0;

    for (int i = 0; i < N; i++) {
        for (int j = 0; j < N; j++) {
            dist[i * N + j] = (i == j ? 0 : INF);
        }
    }

    for (int i = 0; i < M; i++) {
        int a, b;
        long long c;
        scanf("%d %d %lld", &a, &b, &c);
        a--; b--;
        if (c < dist[a * N + b]) {
            dist[a * N + b] = c;
            dist[b * N + a] = c;
        }
    }

    // Floyd-Warshall to compute shortest distances between all pairs
    for (int k = 0; k < N; k++) {
        for (int i = 0; i < N; i++) {
            long long dik = dist[i * N + k];
            if (dik == INF) continue;
            for (int j = 0; j < N; j++) {
                long long dkj = dist[k * N + j];
                if (dkj == INF) continue;
                long long nd = dik + dkj;
                if (nd < dist[i * N + j]) dist[i * N + j] = nd;
            }
        }
    }

    // Build graph where an edge exists if reachable with one full tank
    for (int i = 0; i < N; i++) {
        for (int j = 0; j < N; j++) {
            if (i == j) fuel[i * N + j] = 0;
            else if (dist[i * N + j] <= L) fuel[i * N + j] = 1;
            else fuel[i * N + j] = INF;
        }
    }

    // Floyd-Warshall on the refuel graph
    for (int k = 0; k < N; k++) {
        for (int i = 0; i < N; i++) {
            long long fik = fuel[i * N + k];
            if (fik == INF) continue;
            for (int j = 0; j < N; j++) {
                long long fkj = fuel[k * N + j];
                if (fkj == INF) continue;
                long long nf = fik + fkj;
                if (nf < fuel[i * N + j]) fuel[i * N + j] = nf;
            }
        }
    }

    int Q;
    scanf("%d", &Q);
    while (Q--) {
        int s, t;
        scanf("%d %d", &s, &t);
        s--; t--;
        if (fuel[s * N + t] == INF) {
            printf("-1\n");
        } else {
            // Number of refuels = number of tank-uses - 1
            printf("%lld\n", fuel[s * N + t] - 1);
        }
    }

    free(dist);
    free(fuel);
    return 0;
}

