int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N, M;
    ll L;
    cin >> N >> M >> L;

    vector<vector<pair<int, ll>>> adj(N);
    for (int i = 0; i < M; ++i) {
        int a, b;
        ll c;
        cin >> a >> b >> c;
        --a; --b;
        if (c <= L) {
            adj[a].push_back({b, c});
            adj[b].push_back({a, c});
        }
    }

    // Step 1: Compute shortest distances between all pairs using Dijkstra from each node
    vector<vector<ll>> dist(N, vector<ll>(N, INF));
    for (int s = 0; s < N; ++s) {
        dist[s][s] = 0;
        priority_queue<pair<ll, int>, vector<pair<ll, int>>, greater<>> pq;
        pq.push({0, s});
        while (!pq.empty()) {
            auto [d, u] = pq.top(); pq.pop();
            if (d != dist[s][u]) continue;
            for (auto [v, w] : adj[u]) {
                if (dist[s][v] > d + w) {
                    dist[s][v] = d + w;
                    pq.push({dist[s][v], v});
                }
            }
        }
    }

    // Step 2: Build new graph where edges exist if shortest distance <= L
    vector<vector<int>> newAdj(N);
    for (int i = 0; i < N; ++i) {
        for (int j = i+1; j < N; ++j) {
            if (dist[i][j] <= L) {
                newAdj[i].push_back(j);
                newAdj[j].push_back(i);
            }
        }
    }

    // Step 3: BFS to compute minimum number of refuels (edges in new graph)
    vector<vector<int>> refuels(N, vector<int>(N, -1));
    for (int s = 0; s < N; ++s) {
        queue<int> q;
        refuels[s][s] = 0;
        q.push(s);
        while (!q.empty()) {
            int u = q.front(); q.pop();
            for (int v : newAdj[u]) {
                if (refuels[s][v] == -1) {
                    refuels[s][v] = refuels[s][u] + 1;
                    q.push(v);
                }
            }
        }
    }

    int Q;
    cin >> Q;
    while (Q--) {
        int s, t;
        cin >> s >> t;
        --s; --t;
        int ans = refuels[s][t];
        if (ans == -1) cout << -1 << '\n';
        else cout << max(0, ans - 1) << '\n'; // Refuel count = edges - 1 (except start)
    }

    return 0;
}

