public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);

        int N = sc.nextInt();
        int M = sc.nextInt();
        long L = sc.nextLong();

        List<List<Edge>> graph = new ArrayList<>();
        for (int i = 0; i < N; i++) graph.add(new ArrayList<>());

        for (int i = 0; i < M; i++) {
            int a = sc.nextInt() - 1;
            int b = sc.nextInt() - 1;
            long c = sc.nextLong();
            graph.get(a).add(new Edge(b, c));
            graph.get(b).add(new Edge(a, c));
        }

        // Build refuel graph: edges where travel possible within one full tank
        List<List<Integer>> refuelGraph = new ArrayList<>();
        for (int i = 0; i < N; i++) refuelGraph.add(new ArrayList<>());

        for (int start = 0; start < N; start++) {
            long[] dist = new long[N];
            Arrays.fill(dist, Long.MAX_VALUE);
            dist[start] = 0;
            PriorityQueue<Node> pq = new PriorityQueue<>(Comparator.comparingLong(n -> n.dist));
            pq.offer(new Node(start, 0));

            while (!pq.isEmpty()) {
                Node cur = pq.poll();
                int u = cur.id;
                if (cur.dist > dist[u]) continue;
                for (Edge e : graph.get(u)) {
                    long nd = dist[u] + e.len;
                    if (nd <= L && nd < dist[e.to]) {
                        dist[e.to] = nd;
                        pq.offer(new Node(e.to, nd));
                    }
                }
            }

            for (int v = 0; v < N; v++) {
                if (v != start && dist[v] <= L) {
                    refuelGraph.get(start).add(v);
                }
            }
        }

        int Q = sc.nextInt();
        while (Q-- > 0) {
            int s = sc.nextInt() - 1;
            int t = sc.nextInt() - 1;

            // BFS on refuelGraph
            int[] refuels = new int[N];
            Arrays.fill(refuels, -1);
            Queue<Integer> queue = new LinkedList<>();
            refuels[s] = 0;
            queue.offer(s);

            while (!queue.isEmpty()) {
                int u = queue.poll();
                if (u == t) break;
                for (int v : refuelGraph.get(u)) {
                    if (refuels[v] == -1) {
                        refuels[v] = refuels[u] + 1;
                        queue.offer(v);
                    }
                }
            }

            System.out.println(refuels[t]);
        }
    }

    static class Edge {
        int to;
        long len;
        Edge(int to, long len) {
            this.to = to;
            this.len = len;
        }
    }

    static class Node {
        int id;
        long dist;
        Node(int id, long dist) {
            this.id = id;
            this.dist = dist;
        }
    }
}

