public class Main {
    static final long INF = (long) 4e18;

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);

        int N = fs.nextInt();
        int M = fs.nextInt();
        long L = fs.nextLong();

        long[][] dist = new long[N][N];
        for (int i = 0; i < N; i++) {
            Arrays.fill(dist[i], INF);
            dist[i][i] = 0;
        }

        for (int i = 0; i < M; i++) {
            int a = fs.nextInt() - 1;
            int b = fs.nextInt() - 1;
            long c = fs.nextLong();
            if (c < dist[a][b]) {
                dist[a][b] = c;
                dist[b][a] = c;
            }
        }

        // Floyd-Warshall: shortest distances between all pairs
        for (int k = 0; k < N; k++) {
            for (int i = 0; i < N; i++) {
                if (dist[i][k] == INF) continue;
                for (int j = 0; j < N; j++) {
                    if (dist[k][j] == INF) continue;
                    long nd = dist[i][k] + dist[k][j];
                    if (nd < dist[i][j]) dist[i][j] = nd;
                }
            }
        }

        // Build graph where an edge exists if reachable with one full tank
        long[][] fuel = new long[N][N];
        for (int i = 0; i < N; i++) {
            Arrays.fill(fuel[i], INF);
            fuel[i][i] = 0;
            for (int j = 0; j < N; j++) {
                if (i != j && dist[i][j] <= L) {
                    fuel[i][j] = 1;
                }
            }
        }

        // Floyd-Warshall on refuel-graph:
        // fuel[i][j] = minimum number of full-tank segments
        for (int k = 0; k < N; k++) {
            for (int i = 0; i < N; i++) {
                if (fuel[i][k] == INF) continue;
                for (int j = 0; j < N; j++) {
                    if (fuel[k][j] == INF) continue;
                    long nd = fuel[i][k] + fuel[k][j];
                    if (nd < fuel[i][j]) fuel[i][j] = nd;
                }
            }
        }

        int Q = fs.nextInt();
        StringBuilder sb = new StringBuilder();
        for (int qi = 0; qi < Q; qi++) {
            int s = fs.nextInt() - 1;
            int t = fs.nextInt() - 1;
            if (fuel[s][t] == INF) {
                sb.append(-1).append('\n');
            } else {
                // First full tank at start does not count as refuel during travel
                sb.append(fuel[s][t] - 1).append('\n');
            }
        }

        System.out.print(sb.toString());
    }

    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            in = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        long nextLong() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);

            long sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }

            long val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }

        int nextInt() throws IOException {
            return (int) nextLong();
        }
    }
}

