import sys
from collections import deque

def main():
    input_data = sys.stdin.read().split()
    idx = 0
    N, M, L, Q = int(input_data[idx]), int(input_data[idx+1]), int(input_data[idx+2]), int(input_data[idx+3])
    idx += 4

    INF = float('inf')
    dist = [[INF]*N for _ in range(N)]
    for i in range(N):
        dist[i][i] = 0

    for _ in range(M):
        u, v, w = int(input_data[idx])-1, int(input_data[idx+1])-1, int(input_data[idx+2])
        idx += 3
        if dist[u][v] > w:
            dist[u][v] = w
            dist[v][u] = w

    # Floyd-Warshall
    for k in range(N):
        for i in range(N):
            if dist[i][k] == INF:
                continue
            for j in range(N):
                if dist[i][k] + dist[k][j] < dist[i][j]:
                    dist[i][j] = dist[i][k] + dist[k][j]

    # Build reachability graph
    adj = [[] for _ in range(N)]
    for i in range(N):
        for j in range(N):
            if i != j and dist[i][j] <= L:
                adj[i].append(j)

    # Precompute BFS from each node
    hops = [[INF]*N for _ in range(N)]
    for s in range(N):
        hops[s][s] = 0
        q = deque([s])
        while q:
            u = q.popleft()
            for v in adj[u]:
                if hops[s][v] == INF:
                    hops[s][v] = hops[s][u] + 1
                    q.append(v)

    results = []
    for _ in range(Q):
        s, t = int(input_data[idx])-1, int(input_data[idx+1])-1
        idx += 2
        if hops[s][t] == INF:
            results.append(-1)
        else:
            results.append(hops[s][t] - 1)

    print('\n'.join(map(str, results)))

